window.docContents[46].resolve({"/ValidatingProofs/#Lean-__________________--Validating-a-Lean-Proof--The-Blue-Double-Check-Marks--Significance":{"contents":"The blue ticks indicate that the theorem statement has been successfully elaborated, according to the syntax and type class instances defined in the current file and its imports, and that the Lean kernel has accepted a proof of that theorem statement that follows from the definitions, theorems and axioms declared in the current file and its imports.\n\n","context":"Lean 中文参考手册\u0009Validating a Lean Proof\u0009The Blue Double Check Marks","header":"Significance","id":"/ValidatingProofs/#Lean-__________________--Validating-a-Lean-Proof--The-Blue-Double-Check-Marks--Significance"},"/releases/v4.18.0/#release-v4___18___0":{"contents":"For this release, 344 changes landed. In addition to the 166 feature additions and 38 fixes listed below there were 13 refactoring changes, 10 documentation improvements, 3 performance improvements, 4 improvements to the test suite and 109 other changes.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009Release Notes","header":"Lean 4.18.0 (2025-04-02)","id":"/releases/v4.18.0/#release-v4___18___0"},"/releases/v4.27.0/#release-v4___27___0":{"contents":"For this release, 372 changes landed. In addition to the 118 feature additions and 71 fixes listed below there were 28 refactoring changes, 13 documentation improvements, 25 performance improvements, 6 improvements to the test suite and 111 other changes.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009Release Notes","header":"Lean 4.27.0 (2026-01-24)","id":"/releases/v4.27.0/#release-v4___27___0"}});